import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import {
	eventNamespace,
	NAMESPACE_PERMISSIONS,
	namespaceForAction,
} from "./permissions.ts";

// registry.json is generated by services/api (TestRegistryIsUpToDate) from
// events.AuthzFor: every topic a client can be sent and the action IAM must
// allow. This service maps an action to a room (NAMESPACE_PERMISSIONS) and, for
// an event with no descriptor, a type prefix to a room (eventNamespace): the
// three must agree, or an event would reach no room or the wrong one.
interface Entry {
	topic: string;
	action: string;
	scope: "entity" | "project";
}
const registry = JSON.parse(
	readFileSync(
		new URL("../../api/internal/events/registry.json", import.meta.url),
		"utf8",
	),
) as {
	realtime: Entry[];
	external: Array<{ prefix: string; action: string; publisher: string }>;
};

describe("the event registry of services/api", () => {
	it("is not empty", () => {
		expect(registry.realtime.length).toBeGreaterThan(50);
	});

	it("gives every topic's action a room", () => {
		const orphans = registry.realtime
			.filter((e) => namespaceForAction(e.action) === undefined)
			.map((e) => `${e.topic} (${e.action})`);
		expect(orphans).toEqual([]);
	});

	it("routes a topic by prefix to the room its action belongs to", () => {
		const mismatches = registry.realtime
			.filter((e) => eventNamespace(e.topic) !== namespaceForAction(e.action))
			.map(
				(e) =>
					`${e.topic}: prefix says ${eventNamespace(e.topic)}, action ${e.action} says ${namespaceForAction(e.action)}`,
			);
		expect(mismatches).toEqual([]);
	});

	it("leaves no room that no topic can reach", () => {
		const used = new Set([
			...registry.realtime.map((e) => e.action),
			...registry.external.map((e) => e.action),
		]);
		const unused = Object.entries(NAMESPACE_PERMISSIONS)
			.filter(([, action]) => !used.has(action))
			.map(([room]) => room);
		expect(unused).toEqual([]);
	});
});
